import 'package:flutter/material.dart';import 'package:flutter_screenutil/flutter_screenutil.dart';import '../../../../Config/app_config.dart';import '../../../../Config/Assets/image_png.dart';import '../../../../Config/Routes/route_name.dart';import '../../../../main.dart';import '../../../../Core/Utils/Extensions/context_extension.dart';import '../../../../Core/Resources/app_colors.dart';import '../../../../Core/Resources/app_fonts.dart';import '../../../../Core/Resources/app_icons.dart';class SliverAppBarHome extends StatelessWidget {  const SliverAppBarHome({    super.key,  });  @override  Widget build(BuildContext context) {    return SliverAppBar(      expandedHeight: 300.h,      flexibleSpace: FlexibleSpaceBar(        background: Stack(          children: [            Positioned.fill(              child: ColorFiltered(                  colorFilter: ColorFilter.mode(                      Color(                        0xff171725,                      ),                      BlendMode.screen),                  child: Image.asset(                    AppImagesPng.appBarHome,                    fit: BoxFit.cover,                  )),            ),            Align(              alignment: Alignment.bottomCenter,              child: Container(                height: 30.h,                decoration: const BoxDecoration(                  color: Colors.white,                  borderRadius: BorderRadius.vertical(                    top: Radius.circular(40),                  ),                ),                child: Center(                    child: Container(                  width: 74.w,                  height: 8.h,                  decoration: BoxDecoration(                    color: AppColors.grayscale30,                    borderRadius: BorderRadius.circular(8.r),                  ),                )),              ),            )          ],        ),        title: _buildTitle(context, true),      ),      backgroundColor: AppColors.backgroundColor,      scrolledUnderElevation: 0,      pinned: true,      leadingWidth: 85.w,      leading: Padding(        padding: const EdgeInsets.symmetric(horizontal: 2.5,vertical: 3.5).r,        child: Container(          clipBehavior: Clip.antiAliasWithSaveLayer,          decoration: BoxDecoration(            color: AppColors.backgroundColor,            border: Border.all(              color: AppColors.backgroundColor,              width: 3,              strokeAlign: BorderSide.strokeAlignOutside,            ),            shape: BoxShape.circle,          ),          child: CircleAvatar(            radius: 24.r,          ),        ),      ),      title: _buildTitle(context),      elevation: 0,      actions: [        AppIcons.notification,        12.horizontalSpace,        InkWell(          onTap: () => kNavigationService.navigateTo(AppRoutes.cart),          child: AppIcons.bag,        ),        AppConfig.customPaddingFromRightLeft.horizontalSpace,      ],    );  }  Column _buildTitle(BuildContext context, [bool black = false]) {    return Column(      crossAxisAlignment: CrossAxisAlignment.start,      children: [        Text(          "Client Name",          style: AppTextStyles.h6SemiBold.copyWith(            color: black ? AppColors.grayscale90 : AppColors.grayscale10,          ),        ),        Text(          context.getGreeting(),          style: AppTextStyles.bodyXtraSmallMedium.copyWith(            color: black ? AppColors.grayscale90 : AppColors.grayscale10,          ),        ),      ],    );  }}